// Package usecase contains the application use cases of the File module:
// registering, serving and deleting files (Release 5.0). Every method
// expects to run inside a garage-scoped transaction so Row-Level Security
// applies.
package usecase

import (
	"context"
	"time"

	"github.com/viettechno/vietgara-backend/internal/file/domain"
)

// Repository is the persistence contract of the file registry. Every method
// only sees live files of the given garage.
type Repository interface {
	// Create inserts f (whose id is generated by the caller).
	Create(ctx context.Context, f *domain.File) error
	// FindByID returns domain.ErrFileNotFound when absent.
	FindByID(ctx context.Context, garageID, fileID string) (*domain.File, error)
	// FindByKey returns domain.ErrFileNotFound when absent.
	FindByKey(ctx context.Context, garageID, key string) (*domain.File, error)
	// SoftDelete returns domain.ErrFileNotFound when absent.
	SoftDelete(ctx context.Context, garageID, fileID, deletedBy string) error
	// KeyByID returns the object key and content type of a live file by its
	// id, whoever owns it; domain.ErrFileNotFound when absent.
	KeyByID(ctx context.Context, fileID string) (key, contentType string, err error)
	// SetActive deactivates or reactivates a file.
	SetActive(ctx context.Context, garageID, fileID string, active bool, updatedBy string) error
}

// Storage is the object store (internal/platform/storage).
type Storage interface {
	Put(ctx context.Context, key, contentType string, data []byte) (string, error)
	PutPrivate(ctx context.Context, key, contentType string, data []byte) error
	Delete(ctx context.Context, key string) error
	PublicURL(key string) string
	SignedURL(ctx context.Context, key string, ttl time.Duration) (string, time.Time, error)
}

// EntityChecker tells whether the entity a file is uploaded for (a part, a
// repair order, ...) exists in the garage. It is implemented in cmd/server
// over the modules that own those entities, so this module imports none of
// them. The garage itself needs no check: its id is the request's.
type EntityChecker interface {
	// EntityExists reports whether an entity of entityType with entityID is
	// a live entity of the garage; an entity type nothing owns is false.
	EntityExists(ctx context.Context, garageID, entityType, entityID string) (bool, error)
}

// UsageChecker tells whether a business row still refers to a file, which
// decides between deleting and deactivating it (FR-CAT-07). It is
// implemented in cmd/server over the modules that hold file keys (the
// garage's logo today).
type UsageChecker interface {
	FileInUse(ctx context.Context, garageID string, f *domain.File) (bool, error)
}
